"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["12649"],{61066(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>u,frontMatter:()=>c,contentTitle:()=>p,toc:()=>l,assets:()=>d});var a=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-product-link","title":"Link payer product","description":"Registers a product (product ID and name) against a payer\'s participant code, so that it can be referenced in ABHA policy links.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-product-link.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-product-link","permalink":"/docs/main/docs/nhcx/v1/api/registry/endpoints/registry-product-link","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Link payer product","sidebar_label":"Link payer product","sidebar_class_name":"api-method api-method--post","description":"Registers a product (product ID and name) against a payer\'s participant code, so that it can be referenced in ABHA policy links.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Update ABHA number","permalink":"/docs/main/docs/nhcx/v1/api/registry/endpoints/registry-update-abhanumber"},"next":{"title":"Submit the de-link payer product","permalink":"/docs/main/docs/nhcx/v1/api/registry/endpoints/registry-product-delink"}}'),r=n(62540),i=n(43023),o=n(75064),s=JSON.parse('{"id":"registry_product_link","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/product/link","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Link payer product","title":"Link payer product","description":"Registers a product (product ID and name) against a payer\'s participant code, so that it can be referenced in ABHA policy links.\\n\\n### Business purpose\\n\\nProducts are the payer\'s catalogue entries that policies[].productid and productname refer to when a beneficiary is linked. This Retrieving API call, described in the OpenAPI document as the API to list products by the payers or insurance companies, is how an insurer places a product in the registry under its own participant code. Doing so makes the product ownership resolvable through /product/getowner and gives providers a stable productId and productName to match against when they resolve coverage for InsurancePlan and preauth.\\n\\n### When to use\\n\\nUse it when a payer introduces a new product, and before any /participant/link/abha/policy call that references that product. It is part of payer-side catalogue setup, ahead of member linking and well ahead of any claim-side workflow. When a product is retired, the counterpart /product/delink removes it. The documentation does not describe versioning or renaming of products; treat a rename as de-link and re-link.\\n\\n### Preconditions\\n\\n- A valid Bearer token from the client-credentials call (POST /get/session, form-urlencoded client_ID, client_secret, grant_type=client_credentials); tokens last 1200 seconds, so refresh before expiry.\\n- HTTP headers Accept: application/json, Content-Type: application/json and bearer_auth: Bearer (the participant service uses bearer_auth, not Authorisation).\\n- Base path for the participant service: https://apisbx.ABDM.gov.in/pmjay/sbxhcx/participanthcxservice (sandbox) or https://apisprod.NHA.gov.in/pmjay/hcx/participanthcxservice (production).\\n- This is a synchronous plain-JSON registry call: no JWE envelope, no x-hcx-* protocol headers and no correlation ID are involved.\\n- The payer or insurance company must already be a registered participant with its own participant code.\\n- Body is ProductLinkRequest with all three fields required: productid, productname and participantcode.\\n\\n### Postconditions\\n\\nOn success the endpoint returns HTTP 200 with ParticipantCreateResponse, whose single optional field participant_code is the machine-generated participant identifier on the HCX instance. No callback follows. The product becomes the value that /product/getowner resolves back to the owning participant and that policy links refer to. Failures return 400, 404 or 500 with the ErrorResponse envelope (TIMESTAMP plus Error with code, message and trace).\\n\\n### Common mistakes\\n\\n- Omitting one of the three required fields; productid, productname and participantcode are all mandatory.\\n- Using a participantcode in the wrong casing or from the wrong environment (sandbox codes look like 100001@sbx, production codes end in @hcx).\\n- Referencing a product in a policy link before it has been linked here, so provider-side product matching later fails.\\n- Expecting product details in the response; only participant_code is returned.\\n- Missing the Accept header or the Bearer prefix on bearer_auth.\\n\\n### Best practices\\n\\n- Keep productid values stable and unique within the payer; providers use productId for product-level matching and productName as the practical policy or coverage code for plan lookup.\\n- Register products before linking members, and verify with /product/getowner that the product resolves to your participant code.\\n- Log the participant_code returned with the product identifiers for reconciliation.\\n- Refresh the Bearer token proactively and retry once on 401.\\n\\n### Related scenario\\n\\nAn insurer launches a new family floater plan. Before its policy administration system can link any member, it calls /product/link with the product ID, the product name that hospitals will see, and the insurer\'s participant code, receiving its participant_code back in the response. It then checks /product/getowner with the product ID to confirm ownership, and begins linking members with /participant/link/abha/policy. Hospitals that later call /participant/get/policies will see the product ID and name, use productName for the InsurancePlan lookup and productId for coverage matching in the preauth.\\n\\n### Specification\\n\\nChapter [Participants and policies](/docs/nhcx/v1/registries) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"productid","type":"string","required":false,"description":"","encrypted":false},{"name":"productname","type":"string","required":false,"description":"","encrypted":false},{"name":"participantcode","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"productid":"PRD-FLOATER-01","productname":"Family Floater Gold","participantcode":"100234@sbx"},"responses":[{"status":"200","description":"On success the endpoint returns HTTP 200 with ParticipantCreateResponse, whose single optional field participant_code is the machine-generated participant identifier on the HCX instance.","example":{"participant_code":"100234@sbx"}}],"tag":"Other operations","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/link \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"productid\\": \\"PRD-FLOATER-01\\",\\n  \\"productname\\": \\"Family Floater Gold\\",\\n  \\"participantcode\\": \\"100234@sbx\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/link \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"productid\\": \\"PRD-FLOATER-01\\",\\n  \\"productname\\": \\"Family Floater Gold\\",\\n  \\"participantcode\\": \\"100234@sbx\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/link\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"productid\\": \\"PRD-FLOATER-01\\",\\n        \\"productname\\": \\"Family Floater Gold\\",\\n        \\"participantcode\\": \\"100234@sbx\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/link\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"productid\\": \\"PRD-FLOATER-01\\",\\n    \\"productname\\": \\"Family Floater Gold\\",\\n    \\"participantcode\\": \\"100234@sbx\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let c={title:"Link payer product",sidebar_label:"Link payer product",sidebar_class_name:"api-method api-method--post",description:"Registers a product (product ID and name) against a payer's participant code, so that it can be referenced in ABHA policy links.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-registry.yaml",generated:!0},p,d={},l=[];function h(e){return(0,r.jsx)(o.A,{operation:s})}function u(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(h,{...e})}):h(e)}}}]);